function validate([grid, k]) {
  if (grid.length < 1 || grid.length > 300) return 'grid needs 1 to 300 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 300) return 'Each row needs 1 to 300 values.';
  for (const row of grid) {
    if (row.length !== n) return 'Every row of grid needs the same length.';
    if (row.some(v => v < 0 || v > 15)) return 'Grid values are between 0 and 15.';
  }
  if (k < 0 || k > 15) return 'k is between 0 and 15.';
  return null;
}

