function countPathsWithXorValue(grid, k) {
  const MOD = 1e9 + 7;
  const m = grid.length;
  const n = grid[0].length;
  // dp[i][j][x] counts the paths from (0, 0) to (i, j) whose XOR is x.
  const dp = Array.from({ length: m }, () => Array.from({ length: n }, () => new Array(16).fill(0)));
  dp[0][0][grid[0][0]] = 1;
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (i === 0 && j === 0) continue;
      for (let x = 0; x < 16; x++) {
        let ways = 0;
        if (i > 0) ways += dp[i - 1][j][x];
        if (j > 0) ways += dp[i][j - 1][x];
        dp[i][j][x ^ grid[i][j]] = ways % MOD;
      }
    }
  }
  return dp[m - 1][n - 1][k];
}

