function countPathsWithXorValue(grid, k) {
  const m = grid.length, n = grid[0].length;
  let count = 0;
  // Walk every right/down path, carrying the XOR of the cells visited so far.
  const walk = (i, j, xor) => {
    const value = xor ^ grid[i][j];
    if (i === m - 1 && j === n - 1) {
      if (value === k) count++;
      return;
    }
    if (i + 1 < m) walk(i + 1, j, value);
    if (j + 1 < n) walk(i, j + 1, value);
  };
  walk(0, 0, 0);
  return count % 1000000007;
}

