function generate(rand, size) {
  const m = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  const n = size === 'large' ? 90 + Math.floor(rand() * 11) : 1 + Math.floor(rand() * 5);
  // Small grids often use only a few values, so that paths with the wanted XOR are common.
  const limit = size === 'large' || rand() < 0.3 ? 16 : 1 + Math.floor(rand() * 4);
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => Math.floor(rand() * limit)));
  const k = Math.floor(rand() * (limit > 4 ? 16 : 4));
  return [grid, k];
}
